add_action( 'woocommerce_order_status_cancelled', 'perfectpixel_decrease_total_sales' );
add_action( 'woocommerce_order_status_refunded', 'perfectpixel_decrease_total_sales' );

function perfectpixel_decrease_total_sales( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order ) {
		return;
	}
	$order_store = $order->get_data_store();
	// Only orders whose sales were counted by WooCommerce, and only once.
	if ( ! $order_store->get_recorded_sales( $order ) ) {
		return;
	}
	$product_store = WC_Data_Store::load( 'product' );
	foreach ( $order->get_items() as $item ) {
		$product_id = $item->get_product_id();
		if ( $product_id && $item->get_quantity() > 0 ) {
			$product_store->update_product_sales( $product_id, absint( $item->get_quantity() ), 'decrease' );
		}
	}
	// Lets WooCommerce count them again if the order goes back to processing/completed.
	$order_store->set_recorded_sales( $order, false );
}
